using System.Security.Claims;
using Core.Authorization;
using Core.Modules;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Modules.Planning;
using Shared.Primitives.Identifiers;

namespace Modules.Planning;

public static class PlanningModuleExtensions
{
    public static IServiceCollection AddPlanningModule(this IServiceCollection services)
    {
        services.AddSingleton<IModuleManifestProvider, PlanningModuleManifestProvider>();
        services.AddSingleton<PlanningRepository>();
        services.AddSingleton<PlanningFormulaEngine>();
        services.AddSingleton<Core.Transactions.ITransactionalPlanningBudgetControlCapability, PlanningBudgetControlCapability>();
        return services;
    }

    public static WebApplication MapPlanningModule(this WebApplication app)
    {
        var g = app.MapGroup("/api/v1/planning").WithTags("Planning").RequireAuthorization().RequireRateLimiting("api").AddModuleLifecycleEnforcement();
        g.MapGet("/cycles", async (Guid? legalEntityId, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.cycles.read", legalEntityId, () => r.ListCyclesAsync(Tenant(h), legalEntityId, ct)));
        g.MapPost("/cycles", async (CreatePlanningCycleRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.cycles.manage", q.LegalEntityId, () => r.CreateCycleAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        foreach (var action in new[] { "open", "submit", "approve", "publish", "close", "archive" })
            g.MapPost("/cycles/{id:guid}/" + action, async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, action is "approve" or "publish" ? "planning.versions.approve" : "planning.cycles.manage", null, () => r.AdvanceCycleAsync(Tenant(h), Actor(h), id, action, ct), ct));
        g.MapPost("/models", async (CreatePlanningModelRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", q.LegalEntityId, () => r.CreateModelAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/model-versions", async (CreateModelVersionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", null, () => r.CreateModelVersionAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/metrics", async (CreateMetricRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", null, () => r.CreateMetricAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/versions", async (CreatePlanVersionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", null, () => r.CreatePlanVersionAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapGet("/versions", async (HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.versions.read", null, () => r.ListPlanVersionsAsync(Tenant(h), Actor(h), ct)));
        g.MapGet("/versions/{id:guid}/compare", async (Guid id, Guid otherVersionId, Guid legalEntityId, DateOnly? from, DateOnly? to, string? metricCode, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await ReadPairScoped(h, r, s, a, "planning.versions.read", legalEntityId, id, otherVersionId, () => r.CompareVersionsAsync(Tenant(h), id, new CompareVersionRequest(otherVersionId, legalEntityId, from, to, metricCode), ct), ct));
        g.MapPost("/versions/{id:guid}/clone", async (Guid id, string? name, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, "planning.versions.edit", "plan_version", id, () => r.ClonePlanVersionAsync(Tenant(h), Actor(h), id, name ?? "", ct), ct, 201));
        foreach (var action in new[] { "submit", "approve", "publish", "close" })
            g.MapPost("/versions/{id:guid}/" + action, async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, action switch { "submit" => "planning.versions.submit", "approve" => "planning.versions.approve", "publish" => "planning.versions.publish", _ => "planning.versions.edit" }, "plan_version", id, () => r.AdvanceVersionAsync(Tenant(h), Actor(h), id, action, ct), ct));
        g.MapPost("/versions/{id:guid}/recalculate", async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, "planning.versions.edit", "plan_version", id, () => r.RecalculateCompleteAsync(Tenant(h), Actor(h), id, ct), ct, 202));
        g.MapPost("/calculation-runs/{id:guid}/retry", async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, "planning.versions.edit", "calculation_run", id, () => r.RetryCalculationAsync(Tenant(h), Actor(h), id, ct), ct, 202));
        g.MapPost("/forecasts/roll", async (RollingForecastRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateSourceScoped(h, r, s, a, l, "planning.versions.edit", q.SourceVersionId, () => r.AdvanceRollingForecastAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/scenarios", async (CreateScenarioRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.scenarios.create", null, () => r.CreateScenarioAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/scenarios/{id:guid}/clone", async (Guid id, string? name, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.scenarios.create", null, () => r.CloneScenarioAsync(Tenant(h), Actor(h), id, name ?? "", ct), ct, 201));
        g.MapPost("/scenarios/{id:guid}/share", async (Guid id, Guid userId, string? accessLevel, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.scenarios.share", null, () => r.ShareScenarioAsync(Tenant(h), Actor(h), id, userId, accessLevel ?? "Read", ct), ct));
        g.MapPost("/scenarios/{id:guid}/adopt-preview", async (Guid id, ScenarioAdoptRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.scenarios.create", null, () => r.AdoptScenarioAsync(Tenant(h), Actor(h), id, q, ct), ct, 201));
        g.MapPost("/dimensions", async (CreateDimensionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", null, () => r.CreateDimensionAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapGet("/dimensions", async (Guid modelVersionId, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.models.read", null, () => r.ListDimensionsAsync(Tenant(h), modelVersionId, ct)));
        g.MapPost("/dimensions/{id:guid}/members", async (Guid id, CreateDimensionMemberRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", null, () => r.AddDimensionMemberAsync(Tenant(h), Actor(h), id, q, ct), ct, 201));
        g.MapGet("/dimensions/{id:guid}/members", async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.models.read", null, () => r.ListDimensionMembersAsync(Tenant(h), id, ct)));
        g.MapPost("/dimensions/mappings", async (CreateDimensionMappingRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", null, () => r.AddDimensionMappingAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/metric-mappings", async (CreateMetricMappingRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", q.LegalEntityId, () => r.CreateMetricMappingAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/metric-mappings/{id:guid}/{action}", async (Guid id, string action, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", null, () => r.AdvanceMetricMappingAsync(Tenant(h), Actor(h), id, action, ct), ct));
        g.MapPost("/formulas", async (CreateFormulaRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", null, () => r.CreateFormulaAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/submissions", async (CreateSubmissionUnitRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", q.LegalEntityId, () => r.CreateSubmissionUnitAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapGet("/submissions", async (Guid? planVersionId, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.versions.read", null, () => r.ListSubmissionUnitsAsync(Tenant(h), Actor(h), planVersionId, ct)));
        g.MapPost("/submissions/{id:guid}/coordinates", async (Guid id, SubmissionCoordinateRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, "planning.versions.edit", "submission", id, () => r.AttachSubmissionCoordinatesAsync(Tenant(h), Actor(h), id, q, ct).ContinueWith(_ => new { attached = q.CoordinateIds.Count }, ct), ct));
        g.MapPost("/submissions/{id:guid}/transition", async (Guid id, SubmissionTransitionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, q.Action.ToLowerInvariant() switch { "submit" => "planning.versions.submit", "approve" => "planning.versions.approve", _ => "planning.versions.edit" }, "submission", id, () => q.Action.ToLowerInvariant() switch { "submit" => r.SubmitSubmissionAsync(Tenant(h), Actor(h), Membership(h), id, q.Reason, ct), "approve" => r.ApproveSubmissionAsync(Tenant(h), Actor(h), Membership(h), id, q.Reason, ct), _ => r.AdvanceSubmissionAsync(Tenant(h), Actor(h), id, q, ct) }, ct));
        g.MapPost("/grids/query", async (GridQueryRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await ReadScoped(h, r, s, a, "planning.versions.read", q.LegalEntityId, q.PlanVersionId, () => r.QueryGridAsync(Tenant(h), q, ct), ct));
        g.MapPost("/grids/write-batch", async (GridWriteRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateGridScoped(h, r, s, a, l, "planning.versions.edit", q.Cells.Select(x => x.LegalEntityId), q.PlanVersionId, () => r.WriteGridAsync(Tenant(h), Actor(h), q, ct), ct));
        g.MapPost("/grids/spread", async (GridWriteRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateGridScoped(h, r, s, a, l, "planning.versions.edit", q.Cells.Select(x => x.LegalEntityId), q.PlanVersionId, () => r.WriteGridAsync(Tenant(h), Actor(h), q, ct), ct));
        g.MapPost("/grids/spread-exact", async (SpreadRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateScoped(h, r, s, a, l, "planning.versions.edit", q.LegalEntityId, q.PlanVersionId, () => r.SpreadAsync(Tenant(h), Actor(h), q, ct), ct));
        g.MapPost("/grids/paste-preview", async (GridWriteRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await ReadGridScoped(h, r, s, a, "planning.versions.read", q.Cells.Select(x => x.LegalEntityId), q.PlanVersionId, () => Task.FromResult<IReadOnlyList<GridCellRequest>>(q.Cells), ct));
        g.MapPost("/assumptions", async (CreateAssumptionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateScoped(h, r, s, a, l, "planning.assumptions.manage", null, q.PlanVersionId, () => r.CreateAssumptionAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapGet("/assumptions", async (Guid planVersionId, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await ReadScoped(h, r, s, a, "planning.versions.read", null, planVersionId, () => r.ListAssumptionsAsync(Tenant(h), planVersionId, ct), ct));
        g.MapPost("/assumptions/{id:guid}/values", async (Guid id, AssumptionValueRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, "planning.assumptions.manage", "assumption", id, () => r.SetAssumptionValueAsync(Tenant(h), id, q, ct).ContinueWith(_ => new { saved = true }, ct), ct));
        g.MapPost("/budget/baselines", async (CreateBaselineRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateScoped(h, r, s, a, l, "planning.budget.manage", null, q.PlanVersionId, () => r.CreateBaselineAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/budget/baselines/{id:guid}/{action}", async (Guid id, string action, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, action.Equals("publish", StringComparison.OrdinalIgnoreCase) ? "planning.versions.publish" : "planning.budget.manage", "budget_baseline", id, () => r.AdvanceBaselineAsync(Tenant(h), Actor(h), id, action, ct), ct));
        g.MapPost("/budget/baselines/{id:guid}/revisions", async (Guid id, RevisionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, "planning.budget.revision", "budget_baseline", id, () => r.ApproveRevisionAsync(Tenant(h), Actor(h), id, q, ct).ContinueWith(_ => new { approved = true }, ct), ct));
        g.MapGet("/budget/baselines/{id:guid}/current", async (Guid id, DateOnly? asOfDate, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await ReadReferenceScoped(h, r, s, a, "planning.budget.read", "budget_baseline", id, () => r.CurrentBudgetAsync(Tenant(h), id, asOfDate, ct), ct));
        g.MapPost("/budget/policies", async (Guid legalEntityId, string name, string mode, string basis, decimal thresholdPercent, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.budget.manage", legalEntityId, () => r.CreatePolicyAsync(Tenant(h), Actor(h), legalEntityId, name, mode, basis, thresholdPercent, ct), ct, 201));
        g.MapPost("/budget/buckets", async (BudgetBucketRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateScoped(h, r, s, a, l, "planning.budget.manage", q.LegalEntityId, q.PlanVersionId, () => r.CreateBucketAsync(Tenant(h), q, ct), ct, 201));
        g.MapPost("/budget/overrides", async (BudgetOverrideRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, "planning.budget_control.override", "budget_bucket", q.BucketId, () => r.RequestBudgetOverrideAsync(Tenant(h), Actor(h), Membership(h), q, ct), ct, 201));
        g.MapGet("/budget/overrides/{id:guid}", async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await ReadReferenceScoped(h, r, s, a, "planning.budget_control.read", "budget_override", id, () => r.GetBudgetOverrideAsync(Tenant(h), id, ct), ct));
        g.MapPost("/budget/overrides/{id:guid}/decision", async (Guid id, BudgetOverrideDecisionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await MutateReferenceScoped(h, r, s, a, l, "planning.budget_control.override.approve", "budget_override", id, () => r.DecideBudgetOverrideAsync(Tenant(h), Actor(h), Membership(h), id, q.Decision, q.Reason, ct), ct));
