        {
            if (!await Access(h, s, a, "planning.workforce.read", null, ct)) return Results.Forbid();
            if (!await r.CanAccessPlanVersionAsync(Tenant(h), Actor(h), planVersionId, "Read", ct)) return Results.Forbid();
            var sensitive = await Access(h, s, a, "planning.workforce.sensitive.read", null, ct);
            return await Execute(() => r.ListWorkforceAsync(Tenant(h), planVersionId, sensitive, ct), ct);
        });
        g.MapPost("/workforce/import-baseline", async (IReadOnlyList<WorkforcePlanRequest> q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => q.Count == 0 ? Results.BadRequest() : await MutateScoped(h, r, s, a, l, "planning.versions.edit", q[0].LegalEntityId, q[0].PlanVersionId, () => r.ImportWorkforceAsync(Tenant(h), Actor(h), q, ct), ct));
