    private static async Task<IResult> Mutate<T>(HttpContext h, IAuthorizationSubjectStore store, IPermissionAuthorizer authorizer, IModuleLifecycleEnforcer lifecycle, string permission, Guid? entity, Func<Task<T>> action, CancellationToken ct, int status = 200)
    { var access = await Access(h, store, authorizer, permission, entity, ct); if (!access) return Results.Forbid(); if (!await lifecycle.CanMutateAsync(Tenant(h), "planning", entity, ct)) return Results.Problem(statusCode: 403, title: "module.lifecycle_readonly", extensions: new Dictionary<string, object?> { ["code"] = "module.lifecycle_readonly" }); return await Execute(action, ct, status); }
    private static async Task<IResult> MutateScoped<T>(HttpContext h, PlanningRepository repository, IAuthorizationSubjectStore store, IPermissionAuthorizer authorizer, IModuleLifecycleEnforcer lifecycle, string permission, Guid? entity, Guid planVersionId, Func<Task<T>> action, CancellationToken ct, int status = 200)
    { var access = await Access(h, store, authorizer, permission, entity, ct); if (!access || !await repository.CanAccessPlanVersionAsync(Tenant(h), Actor(h), planVersionId, "Edit", ct)) return Results.Forbid(); if (!await lifecycle.CanMutateAsync(Tenant(h), "planning", entity, ct)) return Results.Problem(statusCode: 403, title: "module.lifecycle_readonly", extensions: new Dictionary<string, object?> { ["code"] = "module.lifecycle_readonly" }); return await Execute(action, ct, status); }
    private static async Task<bool> Access(HttpContext h, IAuthorizationSubjectStore store, IPermissionAuthorizer authorizer, string permission, Guid? entity, CancellationToken ct)
    { if (!Guid.TryParse(h.User.FindFirstValue("tenant_id"), out var tenantId) || !Guid.TryParse(h.User.FindFirstValue("membership_id"), out var membershipId)) return false; var subject = await store.LoadAsync(new TenantId(tenantId), membershipId, ct); if (subject is null) return false; var scope = entity is { } e ? PermissionScope.ForLegalEntity(new TenantId(tenantId), new LegalEntityId(e)) : PermissionScope.ForTenant(new TenantId(tenantId)); return authorizer.Authorize(subject, permission, scope); }
    private static async Task<IResult> Execute<T>(Func<Task<T>> action, CancellationToken ct, int status = 200) { try { var value = await action(); return status == 201 ? Results.Created("", value) : status == 202 ? Results.Accepted("", value) : Results.Ok(value); } catch (PlanningException ex) { var code = ex.Code; var sc = code.Contains("not_found", StringComparison.Ordinal) ? 404 : code is "planning.owner_module_unavailable" ? 403 : code.Contains("immutable", StringComparison.Ordinal) || code.Contains("insufficient", StringComparison.Ordinal) || code.Contains("transition", StringComparison.Ordinal) ? 409 : 400; return Results.Problem(statusCode: sc, title: code, extensions: new Dictionary<string, object?> { ["code"] = code }); } }

    private static async Task<Guid> RefreshActualsWhenOwnersAreAvailableAsync(ActualRefreshRequest request, HttpContext httpContext, PlanningRepository repository, IModuleLifecycleEnforcer lifecycle, CancellationToken ct)
    {
        // Payroll and Purchasing are the owner contracts that can contribute live actual/commitment facts to this refresh.
        foreach (var moduleId in new[] { "payroll", "purchasing" })
            if (!string.Equals(await lifecycle.GetStatusAsync(Tenant(httpContext), moduleId, null, ct), "Active", StringComparison.OrdinalIgnoreCase))
                throw new PlanningException("planning.owner_module_unavailable");
        return await repository.RefreshActualsAsync(Tenant(httpContext), Actor(httpContext), request, ct);
    }
}

